```go
// Package epaxos implements the dependency-graph core of the EPaxos
// leaderless replication protocol: conflict-key tracking, per-command
// sequence numbers, fast/slow commit paths, recovery of an uncommitted
// instance, and a deterministic SCC-based execution order.
package epaxos

import "fmt"

type Status int

const (
	PreAccepted Status = iota
	Accepted
	Committed
	Executed
)

// CmdID identifies a command instance. Instances are numbered independently
// per replica, so CmdID is the pair (Replica, Instance).
type CmdID struct {
	Replica  int
	Instance int
}

func (c CmdID) Less(o CmdID) bool {
	if c.Replica != o.Replica {
		return c.Replica < o.Replica
	}
	return c.Instance < o.Instance
}

func (c CmdID) String() string { return fmt.Sprintf("r%d-i%d", c.Replica, c.Instance) }

// Command is a proposed state-machine command. Keys are the conflict keys it
// declares: two commands conflict iff they share at least one key.
type Command struct {
	ID   CmdID
	Keys []string
	Op   string
}

func (c Command) ConflictsWith(o Command) bool {
	for _, a := range c.Keys {
		for _, b := range o.Keys {
			if a == b {
				return true
			}
		}
	}
	return false
}

// Instance is one replica's record of a command.
type Instance struct {
	Cmd    Command
	Seq    int
	Deps   map[CmdID]bool
	Status Status
}

func cloneDeps(d map[CmdID]bool) map[CmdID]bool {
	out := make(map[CmdID]bool, len(d))
	for k, v := range d {
		if v {
			out[k] = true
		}
	}
	return out
}

func unionDeps(dst, src map[CmdID]bool) {
	for k := range src {
		dst[k] = true
	}
}

func sameDeps(a, b map[CmdID]bool) bool {
	if len(a) != len(b) {
		return false
	}
	for k := range a {
		if !b[k] {
			return false
		}
	}
	return true
}
