### `graph.go` — SCC + deterministic execution order

```go
package epaxos

import (
	"container/heap"
	"sort"
)

// ExecutionOrder computes the single deterministic execution sequence for a
// set of committed instances.
//
// 1. extract the committed subgraph,
// 2. compute strongly connected components (Tarjan, iterative),
// 3. topologically sort the condensation with a min-heap keyed by each
//    component's smallest (Seq, Replica, Instance),
// 4. within a component order by (Seq, Replica, Instance).
func ExecutionOrder(instances map[CmdID]*Instance) []CmdID {
	var nodes []CmdID
	for id, in := range instances {
		if in.Status >= Committed {
			nodes = append(nodes, id)
		}
	}
	sort.Slice(nodes, func(i, j int) bool { return nodes[i].Less(nodes[j]) })
	if len(nodes) == 0 {
		return nil
	}

	present := make(map[CmdID]bool, len(nodes))
	for _, id := range nodes {
		present[id] = true
	}

	// Precedence adjacency: succ[dep] lists nodes that depend on dep.
	succ := make(map[CmdID][]CmdID)
	for _, id := range nodes {
		for dep := range instances[id].Deps {
			if dep == id || !present[dep] {
				continue
			}
			succ[dep] = append(succ[dep], id)
		}
	}
	for k := range succ {
		sort.Slice(succ[k], func(i, j int) bool { return succ[k][i].Less(succ[k][j]) })
	}

	comps := sccs(nodes, succ)

	instLess := func(a, b CmdID) bool {
		ia, ib := instances[a], instances[b]
		if ia.Seq != ib.Seq {
			return ia.Seq < ib.Seq
		}
		return a.Less(b)
	}
	for _, comp := range comps {
		sort.Slice(comp, func(i, j int) bool { return instLess(comp[i], comp[j]) })
	}

	compOf := make(map[CmdID]int, len(nodes))
	for ci, comp := range comps {
		for _, n := range comp {
			compOf[n] = ci
		}
	}

	c := len(comps)
	adjC := make([][]int, c)
	indeg := make([]int, c)
	seen := make(map[[2]int]bool)
	for _, dep := range nodes {
		du := compOf[dep]
		for _, node := range succ[dep] {
			cv := compOf[node]
			if du == cv {
				continue
			}
			e := [2]int{du, cv}
			if seen[e] {
				continue
			}
			seen[e] = true
			adjC[du] = append(adjC[du], cv)
			indeg[cv]++
		}
	}

	h := &compHeap{}
	for ci := 0; ci < c; ci++ {
		if indeg[ci] == 0 {
			head := comps[ci][0]
			heap.Push(h, compItem{ci: ci, seq: instances[head].Seq, id: head})
		}
	}
	order := make([]CmdID, 0, len(nodes))
	for h.Len() > 0 {
		it := heap.Pop(h).(compItem)
		order = append(order, comps[it.ci]...)
		for _, nxt := range adjC[it.ci] {
			indeg[nxt]--
			if indeg[nxt] == 0 {
				head := comps[nxt][0]
				heap.Push(h, compItem{ci: nxt, seq: instances[head].Seq, id: head})
			}
		}
	}
	return order
}

// sccs returns the strongly connected components. adj is a successor
// (precedence) adjacency list. Iterative Tarjan avoids recursion limits.
func sccs(nodes []CmdID, adj map[CmdID][]CmdID) [][]CmdID {
	index := make(map[CmdID]int, len(nodes))
	low := make(map[CmdID]int, len(nodes))
	onStack := make(map[CmdID]bool, len(nodes))
	for _, n := range nodes {
		index[n] = -1
	}
	var stack []CmdID
	var comps [][]CmdID
	counter := 0

	type frame struct {
		v  CmdID
		ei int
	}

	for _, start := range nodes {
		if index[start] != -1 {
			continue
		}
		work := []frame{{v: start}}
		for len(work) > 0 {
			f := &work[len(work)-1]
			v := f.v
			if f.ei == 0 {
				index[v] = counter
				low[v] = counter
				counter++
				stack = append(stack, v)
				onStack[v] = true
			}
			if f.ei < len(adj[v]) {
				w := adj[v][f.ei]
				f.ei++
				if index[w] == -1 {
					work = append(work, frame{v: w})
				} else if onStack[w] && index[w] < low[v] {
					low[v] = index[w]
				}
				continue
			}
			if low[v] == index[v] {
				var comp []CmdID
				for {
					w := stack[len(stack)-1]
					stack = stack[:len(stack)-1]
					onStack[w] = false
					comp = append(comp, w)
					if w == v {
						break
					}
				}
				comps = append(comps, comp)
			}
			work = work[:len(work)-1]
			if len(work) > 0 {
				parent := work[len(work)-1].v
				if low[v] < low[parent] {
					low[parent] = low[v]
				}
			}
		}
	}
	return comps
}

type compItem struct {
	ci  int
	seq int
	id  CmdID
}

type compHeap struct{ items []compItem }

func (h compHeap) Len() int { return len(h.items) }
func (h compHeap) Less(i, j int) bool {
	a, b := h.items[i], h.items[j]
	if a.seq != b.seq {
		return a.seq < b.seq
	}
	return a.id.Less(b.id)
}
func (h compHeap) Swap(i, j int) { h.items[i], h.items[j] = h.items[j], h.items[i] }
func (h *compHeap) Push(x any)   { h.items = append(h.items, x.(compItem)) }
func (h *compHeap) Pop() any {
	old := h.items
	n := len(old)
	x := old[n-1]
	h.items = old[:n-1]
	return x
}
