### `cluster.go` — deterministic EPaxos simulation (fast/slow/recovery)

```go
package epaxos

// Deterministic, single-process simulation of the EPaxos message flow.
// Messages sit in a FIFO queue and are processed until quiescence.

type msgKind int

const (
	mPreAccept msgKind = iota
	mPreAcceptReply
	mAccept
	mAcceptReply
	mCommit
	mPrepare
	mPrepareReply
)

type message struct {
	kind   msgKind
	from   int
	to     int
	cmd    Command
	seq    int
	deps   map[CmdID]bool
	status Status
	has    bool
}

type seqDeps struct {
	seq  int
	deps map[CmdID]bool
}

type propState struct {
	cmd            Command
	seq            int
	deps           map[CmdID]bool
	preGot         int
	preExpected    int
	allSame        bool
	replies        []seqDeps
	acceptGot      int
	acceptExpected int
	phase          int // 0=pre-accept, 1=accept, 2=done
}

type recoverState struct {
	preGot         int
	preExpected    int
	bestSeq        int
	bestDeps       map[CmdID]bool
	haveValue      bool
	cmd            Command
	phase          int
	acceptGot      int
	acceptExpected int
}

// Replica holds the local EPaxos state of one node.
type Replica struct {
	ID        int
	N         int
	crashed   bool
	instances map[CmdID]*Instance
	executed  map[CmdID]bool
	execLog   []Command
	nextInst  int
	props     map[CmdID]*propState
	recovs    map[CmdID]*recoverState
}

// Cluster is a deterministic simulation of N EPaxos replicas.
type Cluster struct {
	N     int
	reps  []*Replica
	queue []message
	Fast  map[CmdID]bool // instances committed on the fast path
	Slow  map[CmdID]bool // instances committed on the slow path
}

func NewCluster(n int) *Cluster {
	c := &Cluster{N: n, Fast: map[CmdID]bool{}, Slow: map[CmdID]bool{}}
	for i := 0; i < n; i++ {
		c.reps = append(c.reps, &Replica{
			ID:        i,
			N:         n,
			instances: map[CmdID]*Instance{},
			executed:  map[CmdID]bool{},
			props:     map[CmdID]*propState{},
			recovs:    map[CmdID]*recoverState{},
		})
	}
	return c
}

func (c *Cluster) Replica(id int) *Replica { return c.reps[id] }
func (c *Cluster) Crash(id int)            { c.reps[id].crashed = true }

// Propose starts a new instance on replica r and returns its id.
func (c *Cluster) Propose(r int, keys []string, op string) CmdID {
	rep := c.reps[r]
	id := CmdID{Replica: r, Instance: rep.nextInst}
	rep.nextInst++
	cmd := Command{ID: id, Keys: append([]string(nil), keys...), Op: op}

	seq, deps := rep.localPreAccept(cmd, 1, nil)
	p := &propState{cmd: cmd, seq: seq, deps: deps, preGot: 1, preExpected: 1, allSame: true}
	p.replies = append(p.replies, seqDeps{seq: seq, deps: cloneDeps(deps)})
	rep.props[id] = p

	for j := range c.reps {
		if j == r || c.reps[j].crashed {
			continue
		}
		p.preExpected++
		c.send(message{kind: mPreAccept, from: r, to: j, cmd: cmd, seq: seq, deps: cloneDeps(deps)})
	}
	return id
}

// Recover drives recovery of instance id from replica by.
func (c *Cluster) Recover(id CmdID, by int) {
	rep := c.reps[by]
	rs := &recoverState{bestDeps: map[CmdID]bool{}}
	rep.recovs[id] = rs
	for j := range c.reps {
		if c.reps[j].crashed {
			continue
		}
		rs.preExpected++
		c.send(message{kind: mPrepare, from: by, to: j, cmd: Command{ID: id}})
	}
}

// Run drains the message queue until quiescence.
func (c *Cluster) Run() {
	for len(c.queue) > 0 {
		m := c.queue[0]
		c.queue = c.queue[1:]
		c.deliver(m)
	}
}

// Execute runs the deterministic SCC execution engine on every live replica.
func (c *Cluster) Execute() {
	for _, rep := range c.reps {
		if rep.crashed {
			continue
		}
		for _, id := range ExecutionOrder(rep.instances) {
			if rep.executed[id] {
				continue
			}
			in := rep.instances[id]
			rep.execLog = append(rep.execLog, in.Cmd)
			rep.executed[id] = true
			in.Status = Executed
		}
	}
}

func (c *Cluster) ExecLog(id int) []string {
	var out []string
	for _, cmd := range c.reps[id].execLog {
		out = append(out, cmd.Op)
	}
	return out
}

func (c *Cluster) send(m message) { c.queue = append(c.queue, m) }

func (c *Cluster) deliver(m message) {
	if m.to < 0 || m.to >= c.N {
		return
	}
	rep := c.reps[m.to]
	if rep.crashed {
		return
	}
	switch m.kind {
	case mPreAccept:
		seq, deps := rep.localPreAccept(m.cmd, m.seq, m.deps)
		c.send(message{kind: mPreAcceptReply, from: m.to, to: m.from, cmd: m.cmd, seq: seq, deps: deps})
	case mPreAcceptReply:
		c.handlePreAcceptReply(m)
	case mAccept:
		rep.localAccept(m.cmd, m.seq, m.deps)
		c.send(message{kind: mAcceptReply, from: m.to, to: m.from, cmd: m.cmd, seq: m.seq, deps: cloneDeps(m.deps)})
	case mAcceptReply:
		c.handleAcceptReply(m)
	case mCommit:
		rep.applyCommit(m.cmd, m.seq, m.deps)
	case mPrepare:
		in := rep.instances[m.cmd.ID]
		reply := message{kind: mPrepareReply, from: m.to, to: m.from, cmd: m.cmd}
		if in != nil {
			reply.has = true
			reply.cmd = in.Cmd
			reply.seq = in.Seq
			reply.deps = cloneDeps(in.Deps)
			reply.status = in.Status
		}
		c.send(reply)
	case mPrepareReply:
		c.handlePrepareReply(m)
	}
}

// localPreAccept merges (seq,deps) and adds every locally-known conflicting
// instance as a dependency, bumping seq above the highest conflicting seq.
func (r *Replica) localPreAccept(cmd Command, seq int, deps map[CmdID]bool) (int, map[CmdID]bool) {
	in := r.instances[cmd.ID]
	if in == nil {
		in = &Instance{Cmd: cmd, Deps: map[CmdID]bool{}, Status: PreAccepted}
		r.instances[cmd.ID] = in
	}
	unionDeps(in.Deps, deps)
	if seq > in.Seq {
		in.Seq = seq
	}
	for id, other := range r.instances {
		if id == cmd.ID || other.Status == Executed {
			continue
		}
		if cmd.ConflictsWith(other.Cmd) {
			in.Deps[id] = true
			if other.Seq+1 > in.Seq {
				in.Seq = other.Seq + 1
			}
		}
	}
	return in.Seq, cloneDeps(in.Deps)
}

func (r *Replica) localAccept(cmd Command, seq int, deps map[CmdID]bool) {
	in := r.instances[cmd.ID]
	if in == nil {
		in = &Instance{Cmd: cmd, Deps: map[CmdID]bool{}}
		r.instances[cmd.ID] = in
	}
	unionDeps(in.Deps, deps)
	if seq > in.Seq {
		in.Seq = seq
	}
	if in.Status < Accepted {
		in.Status = Accepted
	}
}

func (r *Replica) applyCommit(cmd Command, seq int, deps map[CmdID]bool) {
	in := r.instances[cmd.ID]
	if in == nil {
		in = &Instance{Cmd: cmd, Deps: map[CmdID]bool{}}
		r.instances[cmd.ID] = in
	}
	in.Cmd = cmd
	in.Seq = seq
	in.Deps = cloneDeps(deps)
	if in.Status < Committed {
		in.Status = Committed
	}
}

func (c *Cluster) handlePreAcceptReply(m message) {
	rep := c.reps[m.to] // m.to is the leader
	p := rep.props[m.cmd.ID]
	if p == nil || p.phase != 0 {
		return
	}
	p.preGot++
	p.replies = append(p.replies, seqDeps{seq: m.seq, deps: m.deps})
	if m.seq != p.seq || !sameDeps(m.deps, p.deps) {
		p.allSame = false
	}
	if p.preGot < p.preExpected {
		return
	}

	if p.allSame {
		c.Fast[m.cmd.ID] = true // single round was enough
		p.phase = 2
		c.broadcastCommit(p.cmd, p.seq, p.deps)
		return
	}

	// Slow path: union deps, take max seq, run one Accept round.
	c.Slow[m.cmd.ID] = true
	seq := p.seq
	deps := cloneDeps(p.deps)
	for _, rd := range p.replies {
		if rd.seq > seq {
			seq = rd.seq
		}
		unionDeps(deps, rd.deps)
	}
	rep.localAccept(p.cmd, seq, deps)
	p.seq = seq
	p.deps = deps
	p.phase = 1
	p.acceptGot = 1
	p.acceptExpected = 1
	for j := range c.reps {
		if j == rep.ID || c.reps[j].crashed {
			continue
		}
		p.acceptExpected++
		c.send(message{kind: mAccept, from: rep.ID, to: j, cmd: p.cmd, seq: seq, deps: cloneDeps(deps)})
	}
}

func (c *Cluster) handleAcceptReply(m message) {
	rep := c.reps[m.to]
	p := rep.props[m.cmd.ID]
	if p == nil || p.phase != 1 {
		return
	}
	p.acceptGot++
	if p.acceptGot < p.acceptExpected {
		return
	}
	p.phase = 2
	c.broadcastCommit(p.cmd, p.seq, p.deps)
}

func (c *Cluster) handlePrepareReply(m message) {
	rep := c.reps[m.to] // m.to is the recoverer
	id := m.cmd.ID
	rs := rep.recovs[id]
	if rs == nil || rs.phase != 0 {
		return
	}
	rs.preGot++
	if m.has {
		if !rs.haveValue || m.seq > rs.bestSeq {
			rs.bestSeq = m.seq
			rs.bestDeps = cloneDeps(m.deps)
			rs.cmd = m.cmd
		} else if m.seq == rs.bestSeq {
			unionDeps(rs.bestDeps, m.deps)
		}
		rs.haveValue = true
	}
	if rs.preGot < rs.preExpected {
		return
	}
	if !rs.haveValue {
		delete(rep.recovs, id)
		return
	}

	// Re-accept the highest-value instance and commit it.
	p := &propState{cmd: rs.cmd, seq: rs.bestSeq, deps: rs.bestDeps, phase: 1, acceptGot: 1, acceptExpected: 1}
	rep.props[id] = p
	rep.localAccept(rs.cmd, rs.bestSeq, rs.bestDeps)
	for j := range c.reps {
		if j == rep.ID || c.reps[j].crashed {
			continue
		}
		p.acceptExpected++
		c.send(message{kind: mAccept, from: rep.ID, to: j, cmd: rs.cmd, seq: rs.bestSeq, deps: cloneDeps(rs.bestDeps)})
	}
	delete(rep.recovs, id)
}

func (c *Cluster) broadcastCommit(cmd Command, seq int, deps map[CmdID]bool) {
	for j := range c.reps {
		if c.reps[j].crashed {
			continue
		}
		c.send(message{kind: mCommit, from: cmd.ID.Replica, to: j, cmd: cmd, seq: seq, deps: cloneDeps(deps)})
	}
}
