### `epaxos_test.go` — convergence, fast path, SCC, recovery

```go
package epaxos

import (
	"reflect"
	"testing"
)

func assertConverged(t *testing.T, c *Cluster) []string {
	t.Helper()
	var want []string
	for i, rep := range c.reps {
		if rep.crashed {
			continue
		}
		got := c.ExecLog(i)
		if want == nil {
			want = got
			continue
		}
		if !reflect.DeepEqual(got, want) {
			t.Fatalf("replica %d executed %v, replica 0 executed %v", i, got, want)
		}
	}
	return want
}

func TestFastPathNoConflict(t *testing.T) {
	c := NewCluster(3)
	a := c.Propose(0, []string{"a"}, "opa")
	b := c.Propose(1, []string{"b"}, "opb")
	d := c.Propose(2, []string{"c"}, "opc")
	c.Run()
	c.Execute()

	for _, id := range []CmdID{a, b, d} {
		if !c.Fast[id] || c.Slow[id] {
			t.Fatalf("instance %v should take the fast path only", id)
		}
	}
	got := assertConverged(t, c)
	want := []string{"opa", "opb", "opc"} // all seq=1, ordered by replica id
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("execution order = %v, want %v", got, want)
	}
}

func TestConflictingKeySCC(t *testing.T) {
	c := NewCluster(3)
	// All three proposals are injected before any message is processed.
	a := c.Propose(0, []string{"x"}, "A")
	b := c.Propose(1, []string{"x"}, "B")
	d := c.Propose(2, []string{"x"}, "C")
	c.Run()
	c.Execute()

	for _, id := range []CmdID{a, b, d} {
		if !c.Slow[id] {
			t.Fatalf("conflicting instance %v should use the slow path", id)
		}
	}
	for _, id := range []CmdID{a, b, d} {
		var seq int
		var deps map[CmdID]bool
		for i, rep := range c.reps {
			in := rep.instances[id]
			if in == nil || in.Status < Committed {
				t.Fatalf("replica %d missing committed instance %v", i, id)
			}
			if i == 0 {
				seq, deps = in.Seq, in.Deps
				continue
			}
			if in.Seq != seq || !sameDeps(in.Deps, deps) {
				t.Fatalf("instance %v diverged: r0=(%d,%v) r%d=(%d,%v)",
					id, seq, deps, i, in.Seq, in.Deps)
			}
		}
	}
	// The three instances form one SCC: each depends on the other two.
	if !(len(c.reps[0].instances[a].Deps) == 2 &&
		len(c.reps[0].instances[b].Deps) == 2 &&
		len(c.reps[0].instances[d].Deps) == 2) {
		t.Fatalf("expected a fully connected 3-cycle")
	}
	got := assertConverged(t, c)
	want := []string{"A", "B", "C"} // A seq2; B,C seq3 -> (seq,replica)
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("SCC execution order = %v, want %v", got, want)
	}
}

func TestRecoveryUncommittedInstance(t *testing.T) {
	c := NewCluster(3)
	base := c.Propose(1, []string{"x"}, "base")
	c.Run()

	lost := c.Propose(0, []string{"x"}, "lost")
	c.Crash(0)
	c.Run()

	for _, j := range []int{1, 2} {
		in := c.reps[j].instances[lost]
		if in == nil || in.Status >= Committed {
			t.Fatalf("r%d: expected uncommitted instance, got %+v", j, in)
		}
	}

	c.Recover(lost, 1)
	c.Run()
	c.Execute()

	if c.reps[1].instances[base].Status < Committed {
		t.Fatalf("base should be committed")
	}
	got := assertConverged(t, c)
	want := []string{"base", "lost"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("recovered execution order = %v, want %v", got, want)
	}
}

func TestIndependentSCCsDeterministic(t *testing.T) {
	c := NewCluster(3)
	_ = c.Propose(0, []string{"x"}, "x0")
	_ = c.Propose(1, []string{"x"}, "x1")
	_ = c.Propose(1, []string{"y"}, "y1")
	_ = c.Propose(2, []string{"y"}, "y2")
	c.Run()
	c.Execute()
	got := assertConverged(t, c)
	if len(got) != 4 {
		t.Fatalf("expected 4 executed commands, got %v", got)
	}
}
